# Change the sheet's today. Validate first so a bad date is a 400, not masked by a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.sheet.ValidateToday
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: score
# While the score log is on: each person's score on the day being left, before the snapshot lines.
score:
  class: net.officefloor.hq.app.rollup.AuditScore
  govern: [ transaction ]
  next: snapshot
# Each person's due-total on the day being left, before any period closes.
snapshot:
  class: net.officefloor.hq.app.rollup.AuditSnapshot
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.sheet.SaveToday
  govern: [ transaction ]
  next: autoClose
# Once the new today is set: every open period past its to-date plus the grace days closes.
autoClose:
  class: net.officefloor.hq.app.period.AutoClosePeriods
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithToday
  govern: [ transaction ]
package net.officefloor.hq.app.role;

/** A user's role on a sheet: clerk (the default for any name), steward,
 * viewer (sees everything, changes nothing) or restricted (acts as a clerk, but the people list shows
 * only the people of the crews they lead or belong to, and themselves). */
public record Role(String sheetId, String user, String role) {
    public static final String CLERK = "clerk";
    public static final String STEWARD = "steward";
    public static final String VIEWER = "viewer";
    public static final String RESTRICTED = "restricted";
}
export const GRADES = ['A', 'B', 'C'] as const;

/** The key of a grade's grace days, dated like the floor. */
export const gradeGraceKey = (grade: string) => `grace-${grade}`;

/** The key of a grade's own proof threshold, dated like the floor. */
export const gradeProofThresholdKey = (grade: string) => `proof-threshold-${grade}`;

/** The key of a grade's own clerk limit, dated like the floor. */
export const gradeClerkLimitKey = (grade: string) => `clerk-limit-${grade}`;

/** The actions of the permission matrix, in the order they are shown. */
export const ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;

/** Who may take each action while its entry is blank. */
export const STANDING_RULE: Record<string, string> = {
  open: 'clerk,steward',
  settle: 'clerk,steward',
  void: 'clerk,steward',
  reassign: 'steward',
  close: 'clerk,steward',
  reopen: 'steward',
};

/** A save of the settings: only those being changed are sent. */
export type SettingsChange = Partial<Omit<Settings, 'dated'>> & { from?: Record<string, string> };

/**
 * A user's role on a sheet. A name with no role assigned is a clerk; a viewer sees everything and changes nothing;
 * a restricted user acts as a clerk but sees on the people list only the people of the crews they lead or
 * belong to (as the person with their name) and that person.

