package net.officefloor.hq.app.period;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.pool.FrozenCuts;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Reopens a closed period, making its due-total, and each person's figure and carried figure, and every pool member's cut for it, live again. Only a role the permission matrix allows (by
 * the standing rule, a steward) may reopen; a period that
 * is not closed, or is locked, is refused.
 */
public class ReopenPeriod {
    public void reopen(@Val Sheet sheet, @Val Period period, PeriodRepository periods, RoleRepository roles, SettingsRepository settings,
            FrozenCuts frozen, HttpServletRequest request, Out<Period> reopenedOut) throws InvalidPeriodException {
        String user = Audit.user(request);
        String role = roles.roleOf(sheet.id(), user);
        if (!settings.find(sheet.id()).allows("reopen", role)) {
            throw new InvalidPeriodException("A " + role + " may not reopen period " + period.name());
        }
        if (!period.closed()) throw new InvalidPeriodException("Period " + period.name() + " is not closed");
        if (period.locked()) throw new InvalidPeriodException("Period " + period.name() + " is locked");
        Period reopened = period.reopen();
        if (!periods.markReopened(reopened)) {
            throw new InvalidPeriodException("Period " + period.name() + " is not closed or is locked");
        }
        periods.deletePersonTotals(reopened);
        periods.deletePersonCarried(reopened);
        frozen.thaw(reopened);
        reopenedOut.set(reopened);
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.plugin.variable.Val;

public class SaveToday {
    public void save(@Val Sheet sheet, @Val LocalDate today, SheetRepository repository) {
        repository.saveToday(sheet.id(), today);
    }
}
